package pe.edu.upeu.autoandes.controller;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.format.annotation.DateTimeFormat; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import java.util.List; import java.net.URI; import java.time.LocalDate; import java.security.Principal; import pe.edu.upeu.autoandes.service.*; import pe.edu.upeu.autoandes.dto.*;
@RestController @RequestMapping("/api/v1/ordenes") @RequiredArgsConstructor public class OrdenController {private final OrdenService service;
@PostMapping public ResponseEntity<OrdenResponseDTO> registrar(@Valid @RequestBody OrdenRequestDTO dto,Principal principal){var r=service.registrar(dto,principal.getName());return ResponseEntity.created(URI.create("/api/v1/ordenes/"+r.id())).body(r);}
@GetMapping public List<OrdenResponseDTO> consultar(@RequestParam(required=false) String placa,@RequestParam(required=false) String estado,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate desde,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate hasta){return service.consultar(placa,estado,desde,hasta);}
@GetMapping("/{id}") public OrdenResponseDTO obtener(@PathVariable Long id){return service.obtener(id);}
@PatchMapping("/{id}/anular") public OrdenResponseDTO anular(@PathVariable Long id,@Valid @RequestBody AnularOrdenRequestDTO dto){return service.anular(id,dto.motivo());}}
